function gliderGeometry(){const p=[0,.04,.78,-1,0,-.12,-.34,.05,.22,0,.12,-.08,.34,.05,.22,1,0,-.12,0,-.03,-.65],idx=[0,1,2,0,2,3,0,3,4,0,4,5,1,6,2,2,6,3,3,6,4,4,6,5],c=[];for(let i=0;i<7;i++)c.push(i===3?.28:.08,i===3?.85:.42,i===3?.9:.48);return{positions:new Float32Array(p),normals:computeNormals(new Float32Array(p),new Uint16Array(idx)),colors:new Float32Array(c),indices:new Uint16Array(idx)}}
function ringGeometry(segments=48){const p=[],c=[],m=[],idx=[];for(let i=0;i<segments;i++){const a=i/segments*TAU,b=(i+1)/segments*TAU;const i0=p.length/3;for(const [r,y] of [[.94,-.04],[1.06,-.04],[1.06,.04],[.94,.04]]){p.push(Math.cos(a)*r,y,Math.sin(a)*r);c.push(.12,.75,1);m.push(2)}const j0=p.length/3;for(const [r,y] of [[.94,-.04],[1.06,-.04],[1.06,.04],[.94,.04]]){p.push(Math.cos(b)*r,y,Math.sin(b)*r);c.push(.12,.75,1);m.push(2)}idx.push(i0,i0+1,j0,i0+1,j0+1,j0,i0+2,i0+3,j0+2,i0+3,j0+3,j0+2,i0,i0+2,j0,i0+2,j0+2,j0,i0+1,j0+1,i0+3,i0+3,j0+1,j0+3)}return createMesh({positions:new Float32Array(p),colors:new Float32Array(c),materials:new Float32Array(m),indices:new Uint32Array(idx)})}

function createInstancedBatch(base,instances,dynamic=false){const vao=gl.createVertexArray();gl.bindVertexArray(vao);const buffers=[];const bindBase=(loc,data,size)=>{const b=gl.createBuffer();buffers.push(b);gl.bindBuffer(gl.ARRAY_BUFFER,b);gl.bufferData(gl.ARRAY_BUFFER,data,gl.STATIC_DRAW);gl.enableVertexAttribArray(loc);gl.vertexAttribPointer(loc,size,gl.FLOAT,false,0,0)};bindBase(0,base.positions,3);bindBase(1,base.normals,3);bindBase(2,base.colors,3);const ib=gl.createBuffer();buffers.push(ib);gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER,ib);gl.bufferData(gl.ELEMENT_ARRAY_BUFFER,base.indices,gl.STATIC_DRAW);const stride=24*4,data=new Float32Array(instances.length*24),instBuf=gl.createBuffer();buffers.push(instBuf);gl.bindBuffer(gl.ARRAY_BUFFER,instBuf);gl.bufferData(gl.ARRAY_BUFFER,data.byteLength,dynamic?gl.DYNAMIC_DRAW:gl.STATIC_DRAW);for(let i=0;i<4;i++){gl.enableVertexAttribArray(4+i);gl.vertexAttribPointer(4+i,4,gl.FLOAT,false,stride,i*16);gl.vertexAttribDivisor(4+i,1)}gl.enableVertexAttribArray(8);gl.vertexAttribPointer(8,4,gl.FLOAT,false,stride,64);gl.vertexAttribDivisor(8,1);gl.enableVertexAttribArray(9);gl.vertexAttribPointer(9,4,gl.FLOAT,false,stride,80);gl.vertexAttribDivisor(9,1);gl.bindVertexArray(null);const batch={vao,buffers,instBuf,data,count:instances.length,indexCount:base.indices.length,indexType:base.indices instanceof Uint32Array?gl.UNSIGNED_INT:gl.UNSIGNED_SHORT,instances,dynamic};updateInstances(batch);return batch}
