function eventEnvelope(t,anticipation=.18,recovery=.25){if(t<anticipation)return smooth(t/anticipation)*.42;if(t>1-recovery)return lerp(1,0,smooth((t-(1-recovery))/recovery));return lerp(.42,1,smooth((t-anticipation)/(1-anticipation-recovery)))}
const director=createWorldDirector({seed:73,minGap:26,maxGap:44,events:[
{name:'tempest',weight:1,duration:16,anticipation:.2,recovery:.3,start(){state.stormAnchor=nearestIsland().island;showBanner('TEMPEST BLOOM','ATMOSPHERIC COLLAPSE DETECTED')},update(e){state.tempest=eventEnvelope(e.t,.2,.3)},end(){state.tempest=0}},
{name:'solar',weight:.82,duration:18,anticipation:.25,recovery:.28,start(){showBanner('SOLAR BRIDGES','ANCIENT ROUTES ARE UNFOLDING')},update(e){state.solar=Math.max(state.solarMemory,eventEnvelope(e.t,.25,.28))},end(){state.solarMemory=Math.min(.32,state.solarMemory+.08);state.solar=state.solarMemory}}
]});
director.on(({type,payload})=>{if(type==='end')showToast(`${payload.event.name==='tempest'?'Tempest dissipated':'Solar route stabilized'}`)});

const keys=new Set();
addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();keys.add(e.code);if(e.repeat)return;if(e.code==='KeyF')toggleFlight();if(e.code==='KeyI')toggleInspection();if(e.code==='Digit1')triggerTempest();if(e.code==='Digit2')triggerSolar();if(e.code==='KeyM')toggleAudio();if(e.code==='Escape'&&state.selected)closeInspection()});
addEventListener('keyup',e=>keys.delete(e.code));
let dragging=false,lastPointer=[0,0],pointerMoved=false;
canvas.addEventListener('pointerdown',e=>{dragging=true;pointerMoved=false;lastPointer=[e.clientX,e.clientY];canvas.setPointerCapture?.(e.pointerId)});
canvas.addEventListener('pointermove',e=>{if(!dragging||state.autopilot||state.selected)return;const dx=e.clientX-lastPointer[0],dy=e.clientY-lastPointer[1];if(Math.abs(dx)+Math.abs(dy)>2)pointerMoved=true;camera.yaw-=dx*.003;camera.pitch=clamp(camera.pitch-dy*.0025,-1.25,1.18);lastPointer=[e.clientX,e.clientY];updateCameraBasis()});
canvas.addEventListener('pointerup',e=>{dragging=false;if(!pointerMoved)pickIsland(e.clientX,e.clientY)});
canvas.addEventListener('wheel',e=>{camera.speed=clamp(camera.speed-e.deltaY*.12,45,340);showToast(`Cruise speed ${Math.round(camera.speed)} u/s`,900)},{passive:true});

function toggleFlight(){if(state.selected)closeInspection();state.autopilot=!state.autopilot;state.manual=!state.autopilot;ui.flightBtn.classList.toggle('active',state.manual);ui.flightBtn.querySelector('span').textContent=state.manual?'AUTOPILOT':'TAKE CONTROL';showToast(state.manual?'Manual flight engaged · WASD / QE / drag':'Autopilot route engaged')}
function triggerTempest(){director.trigger('tempest');ui.stormBtn.classList.add('active');setTimeout(()=>ui.stormBtn.classList.remove('active'),1200)}
function triggerSolar(){director.trigger('solar');ui.solarBtn.classList.add('active');setTimeout(()=>ui.solarBtn.classList.remove('active'),1200)}
ui.flightBtn.addEventListener('click',toggleFlight);ui.stormBtn.addEventListener('click',triggerTempest);ui.solarBtn.addEventListener('click',triggerSolar);ui.scanBtn.addEventListener('click',toggleInspection);ui.closeInspection.addEventListener('click',closeInspection);

function toggleInspection(){if(state.selected){closeInspection();return}let nearest=islands[0],best=Infinity;for(const island of islands){const d=vlen(vsub(island.pos,camera.pos));if(d<best){best=d;nearest=island}}openInspection(nearest)}
function openInspection(island){state.selected=island;state.autopilot=false;state.manual=false;camera.orbitAngle=Math.atan2(camera.pos[0]-island.pos[0],camera.pos[2]-island.pos[2]);ui.inspection.classList.add('open');ui.scanBtn.classList.add('active');ui.mission.style.opacity='.2';ui.scanId.textContent=island.id;ui.scanName.textContent=island.name;ui.scanDesc.textContent=island.desc;ui.scanBiome.textContent=island.biome;ui.scanAge.textContent=island.age;showToast(`Deep scan locked: ${island.name}`)}
function closeInspection(){state.selected=null;ui.inspection.classList.remove('open');ui.scanBtn.classList.remove('active');ui.mission.style.opacity='';state.autopilot=true;state.manual=false;showToast('Returning to expedition route')}
function projectToScreen(world){const clip=transformPoint(viewProj,world);return{x:(clip[0]*.5+.5)*innerWidth,y:(-.5*clip[1]+.5)*innerHeight,z:clip[2]}}
function pickIsland(x,y){let best=null,bestD=52;for(const island of islands){const p=projectToScreen(vadd(island.pos,v3(0,island.height*.15,0)));if(p.z<-1||p.z>1)continue;const d=Math.hypot(x-p.x,y-p.y);if(d<bestD){bestD=d;best=island}}if(best)openInspection(best);else if(state.manual)showToast('Drag to look · WASD to fly',1200)}

const touch={moveX:0,moveY:0,lookId:null,stickId:null};
function bindTouch(){let origin=[0,0];ui.stick.addEventListener('pointerdown',e=>{touch.stickId=e.pointerId;origin=[e.clientX,e.clientY];ui.stick.setPointerCapture(e.pointerId);if(state.autopilot)toggleFlight()});ui.stick.addEventListener('pointermove',e=>{if(e.pointerId!==touch.stickId)return;touch.moveX=clamp((e.clientX-origin[0])/38,-1,1);touch.moveY=clamp((e.clientY-origin[1])/38,-1,1);ui.stick.style.setProperty('--x',`${touch.moveX*28}px`);ui.stick.style.setProperty('--y',`${touch.moveY*28}px`)});const end=e=>{if(e.pointerId!==touch.stickId)return;touch.stickId=null;touch.moveX=touch.moveY=0;ui.stick.style.setProperty('--x','0px');ui.stick.style.setProperty('--y','0px')};ui.stick.addEventListener('pointerup',end);ui.stick.addEventListener('pointercancel',end);let lookLast=[0,0];ui.look.addEventListener('pointerdown',e=>{touch.lookId=e.pointerId;lookLast=[e.clientX,e.clientY];ui.look.setPointerCapture(e.pointerId);if(state.autopilot)toggleFlight()});ui.look.addEventListener('pointermove',e=>{if(e.pointerId!==touch.lookId||state.selected)return;camera.yaw-=(e.clientX-lookLast[0])*.004;camera.pitch=clamp(camera.pitch-(e.clientY-lookLast[1])*.003,-1.2,1.12);lookLast=[e.clientX,e.clientY];updateCameraBasis()});ui.look.addEventListener('pointerup',e=>{if(e.pointerId===touch.lookId)touch.lookId=null})}
bindTouch();

let audio=null;
async function toggleAudio(){if(!audio){const Ctx=window.AudioContext||window.webkitAudioContext;if(!Ctx){showToast('Web Audio is unavailable');return}const ctx=new Ctx(),gain=ctx.createGain(),filter=ctx.createBiquadFilter(),hum=ctx.createOscillator(),humGain=ctx.createGain();const buffer=ctx.createBuffer(1,ctx.sampleRate*2,ctx.sampleRate),data=buffer.getChannelData(0),rnd=mulberry32(7721);for(let i=0;i<data.length;i++)data[i]=(rnd()*2-1)*.34;const noise=ctx.createBufferSource();noise.buffer=buffer;noise.loop=true;filter.type='lowpass';filter.frequency.value=520;filter.Q.value=.8;hum.type='sine';hum.frequency.value=46;humGain.gain.value=.04;gain.gain.value=0;noise.connect(filter).connect(gain);hum.connect(humGain).connect(gain);gain.connect(ctx.destination);noise.start();hum.start();audio={ctx,gain,filter,hum,humGain,noise,on:false}}if(audio.ctx.state==='suspended')await audio.ctx.resume();audio.on=!audio.on;audio.gain.gain.setTargetAtTime(audio.on?.23:0,audio.ctx.currentTime,.12);ui.soundBtn.classList.toggle('active',audio.on);ui.soundBtn.setAttribute('aria-pressed',String(audio.on));ui.soundBtn.querySelector('span').textContent=audio.on?'SOUND ON':'SOUND OFF';showToast(audio.on?'Aether soundscape enabled':'Soundscape muted')}
ui.soundBtn.addEventListener('click',toggleAudio);

const coreRaw=crystalGeometry(),coreMesh=createMesh({positions:coreRaw.positions,normals:coreRaw.normals,colors:coreRaw.colors,materials:new Float32Array(coreRaw.positions.length/3).fill(2),indices:coreRaw.indices});
const linePos=new Float32Array(scanLines.maxVertices*3),lineCol=new Float32Array(scanLines.maxVertices*3),lightPos=new Float32Array(lightningLines.maxVertices*3),lightCol=new Float32Array(lightningLines.maxVertices*3);
function updateScanLines(){let n=0;if(state.selected&&state.inspect>.02){const s=state.selected,base=s.pos;for(let ringIndex=0;ringIndex<3;ringIndex++){const radius=s.radius*(.42+ringIndex*.19),y=base[1]-s.height*(.08+ringIndex*.12);for(let i=0;i<48;i++){const a=i/48*TAU,b=(i+1)/48*TAU;for(const q of [a,b]){linePos[n*3]=base[0]+Math.cos(q)*radius;linePos[n*3+1]=y+Math.sin(q*3+s.seed)*2;linePos[n*3+2]=base[2]+Math.sin(q)*radius;lineCol[n*3]=.14;lineCol[n*3+1]=.82;lineCol[n*3+2]=1;n++}}}for(let gz=-1;gz<=1;gz++)for(let gx=-1;gx<=1;gx++){const x=base[0]+gx*s.radius*.24,z=base[2]+gz*s.radius*.24;field.sample(x,z,fieldSample);const start=v3(x,base[1]+s.height*.3,z),end=vadd(start,v3(fieldSample[0]*1.8,fieldSample[2]*9,fieldSample[1]*1.8));for(const p of [start,end]){linePos[n*3]=p[0];linePos[n*3+1]=p[1];linePos[n*3+2]=p[2];lineCol[n*3]=.2;lineCol[n*3+1]=.62+.2*fieldSample[2];lineCol[n*3+2]=1;n++}}const coreTop=vadd(base,v3(0,-s.height*.35,0));for(let spoke=0;spoke<6;spoke++){const a=spoke/6*TAU+state.time*.12;const end=vadd(coreTop,v3(Math.cos(a)*s.radius*.52,Math.sin(a*3)*s.height*.08,Math.sin(a)*s.radius*.52));for(const p of [coreTop,end]){linePos[n*3]=p[0];linePos[n*3+1]=p[1];linePos[n*3+2]=p[2];lineCol[n*3]=.78;lineCol[n*3+1]=.38;lineCol[n*3+2]=1;n++}}}updateLineMesh(scanLines,linePos.subarray(0,n*3),lineCol.subarray(0,n*3))}
function updateLightningLines(){let n=0;if(state.tempest>.025){const c=(state.stormAnchor||islands[0]).pos;for(let bolt=0;bolt<11;bolt++){const a=bolt/11*TAU+Math.sin(state.time*.7+bolt)*.18,rad=lerp(30,190,(bolt%5)/4),start=vadd(c,v3(Math.cos(a)*rad,lerp(70,260,(bolt%4)/3),Math.sin(a)*rad)),end=vadd(c,v3(Math.cos(a+.25)*rad*.35,lerp(-70,35,(bolt%3)/2),Math.sin(a+.25)*rad*.35));let last=start;for(let j=1;j<=7;j++){const t=j/7,p=vlerp(start,end,t),wobble=(1-Math.abs(t-.5)*2)*18;p[0]+=Math.sin(state.time*9+bolt*3+j*2.7)*wobble;p[2]+=Math.cos(state.time*8+bolt*2+j*3.1)*wobble;for(const q of [last,p]){lightPos[n*3]=q[0];lightPos[n*3+1]=q[1];lightPos[n*3+2]=q[2];lightCol[n*3]=.45;lightCol[n*3+1]=.72;lightCol[n*3+2]=1;n++}last=p}}}updateLineMesh(lightningLines,lightPos.subarray(0,n*3),lightCol.subarray(0,n*3))}

function updateParticles(dt){for(const batch of [cloudBatch,moteBatch]){const stride=batch.type===0?4:2;for(let i=state.frame%stride;i<batch.count;i+=stride){const k=i*3,x=batch.positions[k],z=batch.positions[k+2];field.sample(x,z,fieldSample);const speed=batch.type===0?.18:.48;batch.positions[k]+=fieldSample[0]*dt*speed*stride;batch.positions[k+2]+=fieldSample[1]*dt*speed*stride;if(batch.positions[k]>1500)batch.positions[k]-=3000;if(batch.positions[k]<-1500)batch.positions[k]+=3000;if(batch.positions[k+2]>1500)batch.positions[k+2]-=3000;if(batch.positions[k+2]<-1500)batch.positions[k+2]+=3000}gl.bindBuffer(gl.ARRAY_BUFFER,batch.pb);gl.bufferSubData(gl.ARRAY_BUFFER,0,batch.positions)}if(state.tempest>.01){const c=(state.stormAnchor||islands[0]).pos;for(let i=0;i<stormBatch.count;i++){const k=i*3,seed=stormBatch.seeds[i],y=lerp(-90,470,seed),tight=lerp(230,28,smooth((y+90)/560)),a=state.time*(.55+seed*.65)+seed*TAU*7,r=tight*(.35+.65*hash2(i,8,12));stormBatch.positions[k]=c[0]+Math.cos(a)*r;stormBatch.positions[k+1]=c[1]+y;stormBatch.positions[k+2]=c[2]+Math.sin(a)*r}gl.bindBuffer(gl.ARRAY_BUFFER,stormBatch.pb);gl.bufferSubData(gl.ARRAY_BUFFER,0,stormBatch.positions)}}

function updateFieldConsumers(){for(const it of vegetationInstances){const p=[it.model[12],it.model[14]];field.sample(p[0],p[1],fieldSample);it.extra[1]=fieldSample[0]*.035;it.extra[2]=fieldSample[1]*.035;it.extra[3]=fieldSample[2]}updateInstances(vegetationBatch);for(const it of crystalInstances){field.sample(it.model[12],it.model[14],fieldSample);it.extra[3]=fieldSample[2]}updateInstances(crystalBatch)}
function updateGliders(dt){for(let i=0;i<gliders.length;i++){const g=gliders[i],it=gliderInstances[i];field.sample(g.pos[0],g.pos[2],fieldSample);const desired=v3(fieldSample[0],Math.sin(state.time*.4+g.phase)*2.2+fieldSample[2]*2.5,fieldSample[1]);vnorm(desired,desired);vscale(desired,g.speed,desired);g.vel[0]=lerp(g.vel[0],desired[0],dt*.72);g.vel[1]=lerp(g.vel[1],desired[1],dt*.6);g.vel[2]=lerp(g.vel[2],desired[2],dt*.72);for(const island of islands){const d=vsub(g.pos,island.pos),dist=vlen(d);if(dist<island.radius*1.35){vnorm(d,d);g.vel[0]+=d[0]*dt*48;g.vel[1]+=Math.abs(d[1])*dt*12+dt*8;g.vel[2]+=d[2]*dt*48}}g.pos[0]+=g.vel[0]*dt;g.pos[1]+=g.vel[1]*dt;g.pos[2]+=g.vel[2]*dt;if(Math.abs(g.pos[0])>1400)g.pos[0]*=-.92;if(Math.abs(g.pos[2])>1400)g.pos[2]*=-.92;g.pos[1]=clamp(g.pos[1],20,580);const yaw=Math.atan2(g.vel[0],g.vel[2]),pitch=-Math.atan2(g.vel[1],Math.hypot(g.vel[0],g.vel[2]));it.model=mCompose(g.pos,[9,9,9],yaw,pitch,Math.sin(state.time+g.phase)*.12);it.extra[3]=fieldSample[2]}updateInstances(gliderBatch)}

function updateCamera(dt,t){const mobile=innerWidth<760;if(state.selected){state.inspect=lerp(state.inspect,1,1-Math.exp(-dt*2.6));const s=state.selected,r=s.radius*(mobile?2.75:2.3),speed=reducedMotion?.045:.105;camera.orbitAngle+=dt*speed;const desired=vadd(s.pos,v3(Math.sin(camera.orbitAngle)*r,(mobile?s.height*.28:-s.height*.08)+22,Math.cos(camera.orbitAngle)*r));camera.pos[0]=lerp(camera.pos[0],desired[0],1-Math.exp(-dt*1.8));camera.pos[1]=lerp(camera.pos[1],desired[1],1-Math.exp(-dt*1.8));camera.pos[2]=lerp(camera.pos[2],desired[2],1-Math.exp(-dt*1.8));vlerp(s.pos,vadd(s.pos,v3(0,-s.height*.42,0)),state.inspect*.88,camera.target);const d=vsub(camera.target,camera.pos);camera.yaw=Math.atan2(d[0],-d[2]);camera.pitch=Math.atan2(d[1],Math.hypot(d[0],d[2]));updateCameraBasis()}else if(state.autopilot){state.inspect=lerp(state.inspect,0,1-Math.exp(-dt*2));const rate=reducedMotion?.025:.052,p=routePoint(t*rate),ahead=routePoint(t*rate+.38);if(!reducedMotion){p[1]+=Math.sin(t*.22)*12;p[0]+=Math.sin(t*.09)*7}camera.pos[0]=lerp(camera.pos[0],p[0],1-Math.exp(-dt*.9));camera.pos[1]=lerp(camera.pos[1],p[1],1-Math.exp(-dt*.9));camera.pos[2]=lerp(camera.pos[2],p[2],1-Math.exp(-dt*.9));const focus=vlerp(ahead,islands[0].pos,.18,camera.target),d=vsub(focus,camera.pos);camera.yaw=Math.atan2(d[0],-d[2]);camera.pitch=Math.atan2(d[1],Math.hypot(d[0],d[2]));updateCameraBasis()}else{state.inspect=lerp(state.inspect,0,1-Math.exp(-dt*2));updateCameraBasis();let f=(keys.has('KeyW')||keys.has('ArrowUp')?1:0)-(keys.has('KeyS')||keys.has('ArrowDown')?1:0)-touch.moveY,s=(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0)+touch.moveX,u=(keys.has('KeyE')?1:0)-(keys.has('KeyQ')?1:0),boost=(keys.has('ShiftLeft')||keys.has('ShiftRight'))?2.1:1;const desired=v3();vadd(desired,vscale(cameraForward,f*camera.speed*boost),desired);vadd(desired,vscale(cameraRight,s*camera.speed*.8*boost),desired);desired[1]+=u*camera.speed*.72;const k=1-Math.exp(-dt*3.2);camera.velocity[0]=lerp(camera.velocity[0],desired[0],k);camera.velocity[1]=lerp(camera.velocity[1],desired[1],k);camera.velocity[2]=lerp(camera.velocity[2],desired[2],k);camera.pos[0]+=camera.velocity[0]*dt;camera.pos[1]+=camera.velocity[1]*dt;camera.pos[2]+=camera.velocity[2]*dt;camera.pos[0]=clamp(camera.pos[0],-1500,1500);camera.pos[1]=clamp(camera.pos[1],-90,850);camera.pos[2]=clamp(camera.pos[2],-1500,1500);vadd(camera.pos,cameraForward,camera.target)}const shakeAmp=reducedMotion?0:state.tempest*3.6;camera.shake[0]=Math.sin(t*17.3)*shakeAmp;camera.shake[1]=Math.sin(t*19.7+2)*shakeAmp*.45;camera.shake[2]=Math.cos(t*15.9)*shakeAmp;const eye=vadd(camera.pos,camera.shake),target=state.selected?camera.target:vadd(eye,cameraForward);mLookAt(eye,target,v3(0,1,0),view);mMul(proj,view,viewProj)}

function updateAudio(){if(!audio?.on)return;const now=audio.ctx.currentTime;field.sample(camera.pos[0],camera.pos[2],fieldSample);audio.filter.frequency.setTargetAtTime(lerp(380,1150,clamp(fieldSample[3],0,1))*(1+state.tempest*.35),now,.2);audio.hum.frequency.setTargetAtTime(42+fieldSample[2]*18+state.solar*16,now,.2);audio.humGain.gain.setTargetAtTime(.025+state.solar*.035+state.tempest*.02,now,.3)}

function update(dt,t){state.time=t;state.frame++;director.update(dt,{camera,islands});if(!director.active){state.tempest=lerp(state.tempest,0,1-Math.exp(-dt*1.3));state.solar=lerp(state.solar,state.solarMemory,1-Math.exp(-dt*.7))}state.fieldTick+=dt;if(state.fieldTick>=.1){state.fieldTick-=.1;rebuildField(t);updateFieldConsumers();updateScanLines()}updateCamera(dt,t);updateGliders(dt);updateParticles(dt);updateLightningLines();updateAudio();state.telemetryTick+=dt;if(state.telemetryTick>.2){state.telemetryTick=0;updateHud()}state.mapTick+=dt;if(state.mapTick>.25){state.mapTick=0;drawMap()}}

let drawCalls=0;
function setMeshCommon(){gl.useProgram(meshProgram);gl.uniformMatrix4fv(meshU.uViewProj,false,viewProj);gl.uniform3fv(meshU.uEye,camera.pos);const sunDir=vnorm(v3(lerp(-.48,.34,state.solar),lerp(.72,.88,state.solar),lerp(.28,-.18,state.solar)));gl.uniform3fv(meshU.uSunDir,sunDir);gl.uniform3fv(meshU.uSunColor,new Float32Array([1.05+state.solar*.28,.92+state.solar*.08,.78-state.tempest*.18]));gl.uniform1f(meshU.uTime,state.time);gl.uniform1f(meshU.uTempest,state.tempest);gl.uniform1f(meshU.uSolar,state.solar);gl.uniform1f(meshU.uInspect,state.inspect)}
function drawMeshObject(mesh,model,opacity=1){gl.uniformMatrix4fv(meshU.uModel,false,model);gl.uniform1f(meshU.uOpacity,opacity);gl.bindVertexArray(mesh.vao);gl.drawElements(mesh.mode,mesh.count,mesh.indexType,0);drawCalls++}
function setInstCommon(kind,material,opacity=1){gl.useProgram(instancedProgram);gl.uniformMatrix4fv(instU.uViewProj,false,viewProj);gl.uniform3fv(instU.uEye,camera.pos);const sunDir=vnorm(v3(lerp(-.48,.34,state.solar),lerp(.72,.88,state.solar),lerp(.28,-.18,state.solar)));gl.uniform3fv(instU.uSunDir,sunDir);gl.uniform3fv(instU.uSunColor,new Float32Array([1.05+state.solar*.28,.92+state.solar*.08,.78-state.tempest*.18]));gl.uniform1f(instU.uTime,state.time);gl.uniform1f(instU.uTempest,state.tempest);gl.uniform1f(instU.uSolar,state.solar);gl.uniform1f(instU.uOpacity,opacity);gl.uniform1i(instU.uKind,kind);gl.uniform1i(instU.uMaterial,material)}
function drawBatch(batch){gl.bindVertexArray(batch.vao);gl.drawElementsInstanced(gl.TRIANGLES,batch.indexCount,batch.indexType,0,batch.count);drawCalls++}
function drawParticleBatch(batch){gl.bindVertexArray(batch.vao);gl.drawArrays(gl.POINTS,0,batch.count);drawCalls++}
function drawLineBatch(batch,alpha){if(!batch.count)return;gl.useProgram(lineProgram);gl.uniformMatrix4fv(lineU.uViewProj,false,viewProj);gl.uniform1f(lineU.uAlpha,alpha);gl.bindVertexArray(batch.vao);gl.drawArrays(gl.LINES,0,batch.count);drawCalls++}
function drawBridges(){const ease=smoother(clamp((state.solar-.04)/.96,0,1)),central=islands[0];if(ease<.01)return;const baseStart=vadd(central.pos,v3(0,central.height*.37,0));for(let i=1;i<islands.length;i++){const dst=islands[i],fullEnd=vadd(dst.pos,v3(0,dst.height*.28,0)),end=vlerp(baseStart,fullEnd,ease),dir=vsub(fullEnd,baseStart),right=vnorm(vcross(v3(0,1,0),dir));for(const offset of [-1,0,1]){const off=vscale(right,11*offset),a=vadd(baseStart,off),b=vadd(end,off),model=mBasisBetween(a,b,offset===0?7.5:3.8,offset===0?2.5:1.7);drawMeshObject(solarBox,model,offset===0?.78:.92)}const nodePos=vlerp(baseStart,end,.93),nodeModel=mCompose(nodePos,[18*ease,18*ease,18*ease],state.time*.08+i*.4);drawMeshObject(ring,nodeModel,.58)}const crownPos=vadd(central.pos,v3(0,central.height*.62,0)),crownModel=mCompose(crownPos,[82*ease,82*ease,82*ease],state.time*.035);drawMeshObject(ring,crownModel,.58);const verticalA=mCompose(crownPos,[118*ease,118*ease,118*ease],state.time*.12,PI*.5,0),verticalB=mCompose(crownPos,[96*ease,96*ease,96*ease],state.time*.09+PI*.5,PI*.5,PI*.5);drawMeshObject(ring,verticalA,.48);drawMeshObject(ring,verticalB,.4)}

function drawTempestCrown(){const amp=state.tempest;if(amp<.02)return;const anchor=state.stormAnchor||islands[0],p=vadd(anchor.pos,v3(0,anchor.height*.24,0));for(let i=0;i<3;i++){const scale=(46+i*34)*amp,model=mCompose(p,[scale,scale,scale],state.time*(.3+i*.11)+i,PI*.5,i*PI/3);drawMeshObject(ring,model,.18+amp*.22)}}

function render(_alpha,t,delta){if(state.contextLost)return;resize();drawCalls=0;state.avgDelta=lerp(state.avgDelta,Math.min(.1,delta),.05);state.fps=1/Math.max(.001,state.avgDelta);if(state.frame%180===0){if(state.avgDelta>.024&&state.renderScale>.5){state.renderScale=Math.max(.5,state.renderScale-.08);resize();showToast(`Adaptive resolution ${Math.round(state.renderScale*100)}%`,1200)}else if(state.avgDelta<.0165&&state.renderScale<1){state.renderScale=Math.min(1,state.renderScale+.04);resize()}}
  gl.bindFramebuffer(gl.FRAMEBUFFER,targetFbo);gl.viewport(0,0,targetWidth,targetHeight);gl.disable(gl.DEPTH_TEST);gl.disable(gl.BLEND);gl.useProgram(skyProgram);gl.uniform1f(skyU.uTime,t);gl.uniform1f(skyU.uTempest,state.tempest);gl.uniform1f(skyU.uSolar,state.solar);gl.uniform1f(skyU.uAspect,targetWidth/targetHeight);gl.uniform2f(skyU.uLook,Math.sin(camera.yaw)*.5,camera.pitch);gl.drawArrays(gl.TRIANGLES,0,3);drawCalls++;
  gl.enable(gl.DEPTH_TEST);gl.depthFunc(gl.LEQUAL);gl.clear(gl.DEPTH_BUFFER_BIT);gl.disable(gl.CULL_FACE);setMeshCommon();for(const island of islands){if(state.selected&&state.inspect>.04&&island===state.selected)continue;drawMeshObject(island.mesh,island.model,1)}for(const structure of structures)drawMeshObject(structure.mesh,structure.model,.96);drawBridges();drawTempestCrown();
  setInstCommon(0,1,1);drawBatch(vegetationBatch);setInstCommon(2,3,1);drawBatch(gliderBatch);
  gl.enable(gl.BLEND);gl.blendFunc(gl.SRC_ALPHA,gl.ONE);gl.depthMask(false);setInstCommon(1,2,.7);drawBatch(crystalBatch);
  if(state.selected&&state.inspect>.02){setMeshCommon();const s=state.selected,corePos=vadd(s.pos,v3(0,-s.height*.38,0)),coreModel=mCompose(corePos,[24*state.inspect,40*state.inspect,24*state.inspect],state.time*.42+s.corePhase,state.time*.11);drawMeshObject(coreMesh,coreModel,.9);for(let i=0;i<3;i++){const rp=vadd(s.pos,v3(0,-s.height*(.18+i*.17),0)),rm=mCompose(rp,[s.radius*(.35+i*.11)*state.inspect,s.radius*(.35+i*.11)*state.inspect,s.radius*(.35+i*.11)*state.inspect],state.time*(.05+i*.02));drawMeshObject(ring,rm,.34)}gl.enable(gl.BLEND);gl.blendFunc(gl.SRC_ALPHA,gl.ONE_MINUS_SRC_ALPHA);gl.depthMask(false);drawMeshObject(s.mesh,s.model,lerp(.82,.34,state.inspect));gl.depthMask(true)}
  gl.useProgram(particleProgram);gl.uniformMatrix4fv(particleU.uViewProj,false,viewProj);gl.uniform1f(particleU.uTime,t);gl.uniform1f(particleU.uPixelRatio,Math.min(devicePixelRatio||1,1.6)*state.renderScale);gl.uniform1f(particleU.uTempest,state.tempest);gl.uniform1f(particleU.uSolar,state.solar);gl.blendFunc(gl.SRC_ALPHA,gl.ONE_MINUS_SRC_ALPHA);drawParticleBatch(cloudBatch);gl.blendFunc(gl.SRC_ALPHA,gl.ONE);drawParticleBatch(moteBatch);if(state.tempest>.01)drawParticleBatch(stormBatch);drawLineBatch(scanLines,state.inspect*.42);drawLineBatch(lightningLines,state.tempest*.9);gl.depthMask(true);gl.disable(gl.BLEND);
  gl.bindFramebuffer(gl.FRAMEBUFFER,null);gl.viewport(0,0,canvas.width,canvas.height);gl.disable(gl.DEPTH_TEST);gl.useProgram(postProgram);gl.activeTexture(gl.TEXTURE0);gl.bindTexture(gl.TEXTURE_2D,targetColor);gl.uniform1i(postU.uScene,0);gl.uniform2f(postU.uTexel,1/targetWidth,1/targetHeight);gl.uniform1f(postU.uTime,t);gl.uniform1f(postU.uTempest,state.tempest);gl.uniform1f(postU.uSolar,state.solar);gl.drawArrays(gl.TRIANGLES,0,3);drawCalls++;
  window.__AETHERIS_DIAGNOSTICS__={ready:true,webgl2:true,gpuRenderer:String(gpuRenderer),softwareRenderer,fps:Number(state.fps.toFixed(1)),renderScale:state.renderScale,drawCalls,particles:cloudBatch.count+moteBatch.count+stormBatch.count,instances:vegetationBatch.count+crystalBatch.count+gliderBatch.count,islands:islands.length,fieldVersion:field.version,tempest:Number(state.tempest.toFixed(3)),solar:Number(state.solar.toFixed(3)),inspection:!!state.selected,canvas:{width:canvas.width,height:canvas.height,clientWidth:canvas.clientWidth,clientHeight:canvas.clientHeight}};
}

function nearestIsland(){let nearest=islands[0],best=Infinity;for(const island of islands){const d=vlen(vsub(island.pos,camera.pos));if(d<best){best=d;nearest=island}}return{island:nearest,distance:best}}
function updateHud(){field.sample(camera.pos[0],camera.pos[2],fieldSample);const wind=Math.hypot(fieldSample[0],fieldSample[1]),near=nearestIsland();ui.field.textContent=clamp(fieldSample[2]+fieldSample[3]*.35,0,1.99).toFixed(2);ui.wind.textContent=wind.toFixed(1);ui.charge.textContent=Math.round(clamp(fieldSample[2],0,1)*100);ui.fps.textContent=Math.round(state.fps);const alt=Math.round(camera.pos[1]+520);ui.location.textContent=`${near.island.name} ${near.distance<260?'Airspace':'Vector'} · Altitude ${alt}m`;const deg=((camera.yaw/TAU*360)%360+360)%360;ui.bearing.textContent=`${deg<45||deg>=315?'N':deg<135?'E':deg<225?'S':'W'} ${String(Math.round(deg)).padStart(3,'0')}°`;const dist=vlen(vsub(camera.pos,islands[0].pos)),progress=clamp(1-dist/1200,0,1);ui.missionProgress.style.width=`${Math.round(progress*100)}%`;if(state.selected){field.sample(state.selected.pos[0],state.selected.pos[2],fieldSample);ui.scanFlux.textContent=(fieldSample[2]+fieldSample[3]*.2).toFixed(2);ui.scanCore.textContent=state.tempest>.5?'Overloaded':state.solar>.6?'Resonant':'Stable'}if(state.tempest>.35){ui.missionTitle.textContent='Ride the Tempest Shear';ui.missionBody.textContent='The storm is rewriting local routes. Hold altitude and watch the Crown lightning lattice.'}else if(state.solar>.55){ui.missionTitle.textContent='Cross the Solar Bridges';ui.missionBody.textContent='Ancient lightways are unfolding between islands. The geometry will persist after the surge.'}else{ui.missionTitle.textContent='Reach the Meridian Crown';ui.missionBody.textContent='Follow the cobalt current toward the central spire. Click any island to enter deep scan.'}}

function drawMap(){const w=mapCanvas.width,h=mapCanvas.height,ctx=mapCtx;ctx.clearRect(0,0,w,h);const grad=ctx.createRadialGradient(w*.5,h*.5,4,w*.5,h*.5,w*.72);grad.addColorStop(0,'rgba(18,64,76,.28)');grad.addColorStop(1,'rgba(2,9,15,.04)');ctx.fillStyle=grad;ctx.fillRect(0,0,w,h);ctx.strokeStyle='rgba(153,225,239,.08)';ctx.lineWidth=1;for(let x=0;x<=w;x+=30){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke()}for(let y=0;y<=h;y+=25){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}const mapPoint=(x,z)=>[w*.5+x/3000*w*.88,h*.5+z/3000*h*.88];ctx.strokeStyle=`rgba(109,244,255,${.18+state.solar*.22})`;ctx.lineWidth=.7;for(let gy=-2;gy<=2;gy++)for(let gx=-3;gx<=3;gx++){const x=gx*360,z=gy*400;field.sample(x,z,fieldSample);const [sx,sy]=mapPoint(x,z),mag=Math.hypot(fieldSample[0],fieldSample[1])||1;ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(sx+fieldSample[0]/mag*8,sy+fieldSample[1]/mag*8);ctx.stroke()}if(state.solar>.08){ctx.strokeStyle=`rgba(255,210,128,${state.solar*.32})`;for(let i=1;i<islands.length;i++){const a=mapPoint(islands[0].pos[0],islands[0].pos[2]),b=mapPoint(islands[i].pos[0],islands[i].pos[2]);ctx.beginPath();ctx.moveTo(...a);ctx.lineTo(...b);ctx.stroke()}}for(const island of islands){const [x,y]=mapPoint(island.pos[0],island.pos[2]);ctx.beginPath();ctx.arc(x,y,clamp(island.radius/34,2.8,5),0,TAU);ctx.fillStyle=island===state.selected?'rgba(255,255,255,.42)':'rgba(4,24,31,.72)';ctx.fill();ctx.strokeStyle=island===state.selected?'rgba(255,255,255,.9)':'rgba(109,244,255,.64)';ctx.stroke()}const [cx,cy]=mapPoint(camera.pos[0],camera.pos[2]);ctx.save();ctx.translate(cx,cy);ctx.rotate(camera.yaw);ctx.fillStyle='#e9fbff';ctx.shadowColor='#aaf6ff';ctx.shadowBlur=7;ctx.beginPath();ctx.moveTo(0,-6);ctx.lineTo(4,5);ctx.lineTo(0,3);ctx.lineTo(-4,5);ctx.closePath();ctx.fill();ctx.restore()}

canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();state.contextLost=true;loop.suspend();showBanner('CONTEXT LOST','REINITIALIZE THE TAB','RENDERER')});canvas.addEventListener('webglcontextrestored',()=>location.reload());
document.addEventListener('visibilitychange',()=>{if(document.hidden)loop.suspend();else loop.resume()});
